from totals import column_totals


def export_csv(rows, totals=False):
    if totals:
        # Compute totals row
        totals_row = column_totals(rows)
        # Render original rows
        rendered_rows = render_rows(rows)
        # Render totals row with mark_last=True
        totals_rendered = render_rows([totals_row], mark_last=True)
        # Combine
        all_rows = rendered_rows + totals_rendered
        return "\n".join(all_rows)
    else:
        return "\n".join(render_rows(rows))

